cat >> src/pixel/scenes.ts <<'EOF'

const cache = new Map<string, Scene>();

/** Scene by key: "hero", "banner:<slug>", "vignette:<kind>", "figure:<n>". Built once per page load. */
export function sceneFor(key: string): Scene {
  const hit = cache.get(key);
  if (hit) return hit;
  const [kind, arg = ''] = key.split(':');
  const scene =
    kind === 'hero'
      ? hero()
      : kind === 'banner'
        ? (BANNERS[arg] ?? BANNERS.about)()
        : kind === 'vignette'
          ? vignette(arg as 'empty' | 'not-found' | 'post-missing')
          : figure(Number(arg));
  cache.set(key, scene);
  return scene;
}
EOF
